    public void applyProperties(GameProfile profile, SkinModel targetSkin) {
        //remove existing skins
        profile.properties().clear();

        if (targetSkin != null) {
            ProfileProperty profileProperty = new ProfileProperty(SkinProperty.SKIN_KEY
