package com.github.games647.changeskin.sponge.task;

import com.flowpowered.math.vector.Vector3d;
import com.github.games647.changeskin.core.model.UserPreference;
import com.github.games647.changeskin.core.model.skin.SkinModel;
import com.github.games647.changeskin.core.shared.task.SharedApplier;
import com.github.games647.changeskin.sponge.ChangeSkinSponge;

import java.util.UUID;

import org.spongepowered.api.Sponge;
import org.spongepowered.api.command.CommandSource;
import org.spongepowered.api.data.Keys;
import org.spongepowered.api.entity.living.player.server.ServerPlayer;
import org.spongepowered.api.entity.living.player.tab.TabList;
import org.spongepowered.api.entity.living.player.tab.TabListEntry;
import org.spongepowered.api.profile.GameProfile;
import org.spongepowered.api.scheduler.Task;
import org.spongepowered.api.world.server.ServerLocation;
import org.spongepowered.api.world.server.ServerWorld;
import org.spongepowered.math.vector.Vector3d;

import net.kyori.adventure.text.Component;

public class SkinApplier extends SharedApplier {

    private final ChangeSkinSponge plugin;
    private final CommandSource invoker;
    private final ServerPlayer receiver;

    public SkinApplier(ChangeSkinSponge plugin, CommandSource invoker, ServerPlayer receiver, SkinModel targetSkin
            , boolean keepSkin) {
        super(plugin.getCore(), targetSkin, keepSkin);

        this.plugin = plugin;
        this.invoker = invoker;
        this.receiver = receiver;
    }

    @Override
    public void run() {
        if (!isConnected()) {
            return;
        }

        //uuid was successful resolved, we could now make a cooldown check
        if (invoker instanceof ServerPlayer) {
            UUID uniqueId = ((ServerPlayer) invoker).uniqueId();
            core.getCooldownService().trackPlayer(uniqueId);
        }

        if (core.getStorage() != null) {
            UserPreference preferences = core.getStorage().getPreferences(receiver.uniqueId());
            save(preferences);
        }

        applySkin();
    }

    @Override
    protected boolean isConnected() {
        return receiver.isOnline();
    }

    @Override
    protected void applyInstantUpdate() {
        plugin.getApi().applySkin(receiver, targetSkin);

        sendUpdate();
        plugin.sendMessage(invoker, "skin-changed");
    }

    @Override
    protected void sendMessage(String key) {
        plugin.sendMessage(invoker, key);
    }

    @Override
    protected void runAsync(Runnable runnable) {
        Task.builder().async()
                .execute(runnable)
                .submit(plugin);
    }

    private void sendUpdate() {
        sendUpdateSelf();

        //triggers an update for others player to see the new skin
        receiver.offer(Keys.VANISH, true);
        receiver.offer(Keys.VANISH, false);
    }

    private void sendUpdateSelf() {
        TabList tabList = receiver.tabList();
        tabList.removeEntry(receiver.uniqueId());

        Component displayName = receiver.displayName().orElse(Component.text(receiver.name()));
        TabListEntry.builder()
                .displayName(displayName)
                .latency(receiver.connection().latency())
                .tabList(tabList)
                .gameMode(receiver.gameMode().get())
                .profile((GameProfile) receiver.profile())
                .build();

        ServerLocation oldLocation = receiver.location();
        Vector3d rotation = receiver.rotation();
        ServerWorld receiverWorld = receiver.world();
        Sponge.server().world()
                .stream()
                .filter(world -> !world.equals(receiverWorld))
                .findFirst()
                .ifPresent(world -> {
                    receiver.setLocation(world.spawnLocation());
                    receiver.setLocationAndRotation(oldLocation, rotation);
                });
    }
}

